import type { Request, Response } from "express";

export type Product = {
  id: string;
  name: string;
  price: number;
  category: "pottery" | "textiles" | "woodwork" | "jewelry";
  image: string;
  featured: boolean;
  description: string;
};

const products: Product[] = [
  // Pottery
  {
    id: "p1",
    name: "Terracotta Serving Bowl",
    price: 68,
    category: "pottery",
    image: "/airo-assets/images/products/pottery-bowl",
    featured: true,
    description:
      "Hand-thrown on the wheel from local terracotta clay, this generous serving bowl is finished with a warm earth glaze. Each piece is unique with subtle variations in color and texture.",
  },
  {
    id: "p2",
    name: "Stoneware Morning Mug",
    price: 38,
    category: "pottery",
    image: "/airo-assets/images/products/pottery-mug",
    featured: false,
    description:
      "Start your day right with this chunky, hand-thrown stoneware mug. Holds 12oz and features a comfortable thumb rest. Dishwasher safe after curing.",
  },
  {
    id: "p3",
    name: "Celadon Bud Vase",
    price: 52,
    category: "pottery",
    image: "/airo-assets/images/products/pottery-vase",
    featured: false,
    description:
      "A slender, elegant vase glazed in soft celadon green. Perfect for a single stem or small wildflower arrangement. Wheel-thrown and hand-trimmed.",
  },
  // Textiles
  {
    id: "t1",
    name: "Merino Wool Throw",
    price: 145,
    category: "textiles",
    image: "/airo-assets/images/products/textiles-throw",
    featured: true,
    description:
      "Woven on a floor loom from 100% merino wool in warm oat and rust tones. Generously sized at 50×70 inches — drape it over a sofa or wrap yourself up.",
  },
  {
    id: "t2",
    name: "Woven Linen Cushion Cover",
    price: 58,
    category: "textiles",
    image: "/airo-assets/images/products/textiles-cushion",
    featured: false,
    description:
      "Hand-woven linen cushion cover in a natural stripe pattern. Fits a standard 18×18 insert. Hidden zipper closure. Machine washable on gentle cycle.",
  },
  {
    id: "t3",
    name: "Market Tote Bag",
    price: 42,
    category: "textiles",
    image: "/airo-assets/images/products/textiles-tote",
    featured: false,
    description:
      "Sturdy hand-woven tote made from undyed natural cotton. Reinforced handles and a flat base make it perfect for farmers markets or everyday errands.",
  },
  // Woodwork
  {
    id: "w1",
    name: "Walnut Charcuterie Board",
    price: 95,
    category: "woodwork",
    image: "/airo-assets/images/products/woodwork-board",
    featured: true,
    description:
      "Hand-cut from a single slab of black walnut, this board showcases the wood's natural grain and character. Finished with food-safe mineral oil and beeswax.",
  },
  {
    id: "w2",
    name: "Floating Wall Shelf",
    price: 120,
    category: "woodwork",
    image: "/airo-assets/images/products/woodwork-shelf",
    featured: false,
    description:
      "Live-edge white oak shelf with hidden bracket mounting. Each shelf is unique — the natural edge is preserved and lightly sanded smooth. Hardware included.",
  },
  {
    id: "w3",
    name: "Turned Maple Bowl",
    price: 78,
    category: "woodwork",
    image: "/airo-assets/images/products/woodwork-bowl",
    featured: false,
    description:
      "Lathe-turned from a solid block of hard maple. The natural figure of the wood creates a beautiful pattern. Finished with pure tung oil for a warm, matte sheen.",
  },
  // Jewelry
  {
    id: "j1",
    name: "Hammered Silver Ring",
    price: 65,
    category: "jewelry",
    image: "/airo-assets/images/products/jewelry-ring",
    featured: false,
    description:
      "Hand-forged from sterling silver sheet and textured with a ball-peen hammer. Available in sizes 5–10. Each ring has a slightly different texture — no two are identical.",
  },
  {
    id: "j2",
    name: "River Stone Pendant",
    price: 88,
    category: "jewelry",
    image: "/airo-assets/images/products/jewelry-necklace",
    featured: true,
    description:
      "A smooth river-tumbled labradorite stone set in a hand-fabricated sterling silver bezel. Hung on a 16-inch oxidized silver chain. The stone catches light beautifully.",
  },
  {
    id: "j3",
    name: "Forged Brass Earrings",
    price: 48,
    category: "jewelry",
    image: "/airo-assets/images/products/jewelry-earrings",
    featured: false,
    description:
      "Lightweight drop earrings hand-forged from raw brass sheet. Hammered for texture and finished with a light patina. Sterling silver ear wires. Hypoallergenic.",
  },
];

export default function handler(req: Request, res: Response) {
  const { featured, category } = req.query;

  let result = [...products];

  if (featured === "true") {
    result = result.filter((p) => p.featured);
  }

  if (category && typeof category === "string") {
    result = result.filter((p) => p.category === category);
  }

  res.json(result);
}

