      setSubscribed(true);
      setEmail('');
    }
  };

  return (
    <footer style={{ backgroundColor: '#3D2314' }} className="text-white">
      <div className="container mx-auto px-6 py-14">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-10 md:gap-8">
          {/* Brand */}
          <div className="space-y-4">
            <img
              src="/airo-assets/images/logo/horizontal?variant=solid"
              alt="Artisan Goods Co."
              className="h-9 w-auto object-contain shrink-0 brightness-0 invert"
            />
            <p className="text-sm leading-relaxed" style={{ color: '#C9B49A' }}>
