                  className="w-full px-4 py-2.5 rounded-lg text-sm bg-white/10 border border-white/20 text-white placeholder:text-white/40 focus:outline-none focus:border-white/50 transition-colors"
                />
                <button
                  type="submit"
                  className="px-5 py-2.5 rounded-lg text-sm font-medium text-white transition-all duration-200 hover:opacity-90"
                  style={{ backgroundColor: '#C1613A' }}
                >
                  Subscribe
                </button>
              </form>
            )}
          </div>
        </div>

        <div
          className="mt-12 pt-6 flex flex-col md:flex-row justify-between items-center gap-3 text-xs"
          style={{ borderTopColor: 'rgba(255,255,255,0.1)', borderTopWidth: 1, color: '#C9B49A' }}
        >
          <span>© {currentYear} Artisan Goods Co. All rights reserved.</span>
          <span>Made with care, shipped with love.</span>
        </div>
      </div>
    </footer>
  );
}

import { motion } from 'motion/react';
import { Link } from 'react-router-dom';
import type { Product } from '../server/api/products/GET';

const categoryColors: Record<Product['category'], string> = {
  pottery: '#C1613A',
  textiles: '#7A8C5E',
  woodwork: '#8B6340',
  jewelry: '#9B7B9E',
};

const categoryLabels: Record<Product['category'], string> = {
  pottery: 'Pottery',
  textiles: 'Textiles',
  woodwork: 'Woodwork',
  jewelry: 'Jewelry',
};

interface ProductCardProps {
  product: Product;
  size?: 'default' | 'large';
}

export default function ProductCard({ product, size = 'default' }: ProductCardProps) {
  const badgeColor = categoryColors[product.category];
  const badgeLabel = categoryLabels[product.category];

  return (
    <motion.article
      whileHover={{ y: -4, boxShadow: '0 12px 32px rgba(61,35,20,0.15)' }}
      transition={{ duration: 0.2, ease: 'easeOut' }}
      className="group bg-card rounded-2xl overflow-hidden border border-muted cursor-pointer"
    >
      <Link to={`/products`} className="block">
        <div
          className={`relative overflow-hidden bg-muted ${
            size === 'large' ? 'aspect-[4/3]' : 'aspect-square'
          }`}
        >
          <img
            src={product.image}
            alt={product.name}
            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
            loading="lazy"
          />
          {/* Category badge */}
          <span
            className="absolute top-3 left-3 px-3 py-1 rounded-full text-xs font-medium text-white"
            style={{ backgroundColor: badgeColor }}
          >
            {badgeLabel}
          </span>
        </div>

        <div className="p-4">
          <h3
            className={`font-semibold text-foreground leading-snug mb-1 ${
              size === 'large' ? 'text-lg' : 'text-base'
